import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object} placement
 * @property {Array<number>} placement.position
 * @property {Array<number>} placement.rotation
 * @property {Array<number>} placement.scale
 * @property {Object} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string): import('three/webgpu').Texture} textureLoader
 * @property {Object<string, Function>} primitives
 * @property {any} fontAtlas
 */

/**
 * Creates a textured plane for the pricing card.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ---------------------------------------------------------------------------
  // Geometry
  // ---------------------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1); // unit plane; scale handled externally

  // ---------------------------------------------------------------------------
  // Texture
  // ---------------------------------------------------------------------------
  const imageUrl = config?.assets?.imageUrl ?? '';
  const tex = ctx.textureLoader(imageUrl);

  // ---------------------------------------------------------------------------
  // Material (node based)
  // ---------------------------------------------------------------------------
  const mapNode = texture(tex);
  const material = new MeshBasicNodeMaterial({ map: mapNode });

  // ---------------------------------------------------------------------------
  // Mesh
  // ---------------------------------------------------------------------------
  const mesh = new Mesh(geometry, material);

  // ---------------------------------------------------------------------------
  // Placement
  // ---------------------------------------------------------------------------
  const pos = config?.placement?.position ?? [0, 0, 0];
  const rot = config?.placement?.rotation ?? [0, 0, 0];
  const scl = config?.placement?.scale ?? [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // ---------------------------------------------------------------------------
  // User data – handlers (none for this element) and cleanup
  // ---------------------------------------------------------------------------
  mesh.userData.handlers = {};

  // store any created GSAP timelines for later kill (none here but kept for pattern)
  const timelines = [];

  mesh.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if it has a dispose method
    if (tex && typeof tex.dispose === 'function') {
      tex.dispose();
    }
    // Kill any GSAP timelines that might have been created
    timelines.forEach((tl) => tl.kill && tl.kill());
  };

  return mesh;
}
